import { mountProductShipping, refreshProductShipping } from './delivery-ui.js';
import { productVisibleForPostal } from './delivery-context.js';
import { createOrderJourney } from './order-ui.js';
import { readMarketplace } from './marketplace-settings.js';
import { resolveSelection, validateCart, TYPE_LABELS } from './product-types.js';
export function createProductExperience({products,state,money,escape,icon,modal,toast}){
  const lines=new Map();let currentId=null,selection={};
  const journey=createOrderJourney({products,lines,modal,syncCart,showCart});
  const safe=escape;
  const attrs=(p,values={},component=null)=>p.type==='variable'?'<div class="attribute-selectors">'+p.attributes.map(a=>'<fieldset><legend>'+safe(a.name)+'</legend>'+a.values.map(v=>{const available=p.variants.some(x=>x.active!==false&&x.stock>0&&x.attributes[a.name]===v&&Object.entries(values).every(([k,val])=>k===a.name||!val||x.attributes[k]===val));return '<button type="button" class="variant-option" data-option="'+safe(v)+'" data-attribute="'+safe(a.name)+'" '+(component!==null?'data-component="'+component+'"':'')+' aria-pressed="'+(values[a.name]===v)+'" '+(!available?'disabled':'')+'>'+safe(v)+'</button>'}).join('')+'</fieldset>').join('')+'<button class="text-link" type="button" data-clear-options '+(component!==null?'data-component="'+component+'"':'')+'>Limpar escolhas</button></div>':'';
  function redrawOptions(){const p=selectedProduct();if(p.type==='variable'){const host=document.querySelector('.type-configuration');host.innerHTML='<div class="type-label">Escolha as opções do produto</div>'+attrs(p,selection.attributes);}else if(p.type==='kit'){p.components.forEach(c=>{const host=document.querySelector('[data-kit-include="'+c.productId+'"]')?.closest('.kit-item')?.querySelector('.kit-item-options')||[...document.querySelectorAll('.kit-item')][p.components.indexOf(c)]?.querySelector('.kit-item-options');if(host)host.innerHTML=attrs(products[c.productId],selection.items[c.productId].attributes,c.productId);});}}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-option],[data-clear-options]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.disabled)return;const target=b.dataset.component!==undefined?selection.items[b.dataset.component]:selection;if(b.hasAttribute('data-clear-options'))target.attributes={};else target.attributes[b.dataset.attribute]=b.dataset.option;redrawOptions();syncSummary();},true);
  function kitRows(p){return `<div class="kit-intro"><span class="type-pill">Kit ${p.kitMode==='closed'?'fechado':'aberto'}</span><h2>${p.kitMode==='closed'?'Um presente completo, do seu jeito.':'Monte o seu presente.'}</h2><p>${p.kitMode==='closed'?'Todos os itens fazem parte do kit. Escolha as variações de cada produto.':'Escolha pelo menos 2 produtos diferentes. Você pode levar parte da seleção ou todos os itens.'}</p></div><div class="kit-items">${p.components.map(c=>{const child=products[c.productId],item=selection.items[c.productId];return `<article class="kit-item ${item.included?'included':''}"><div class="kit-item-head"><img src="${child.image}" alt="${safe(child.name)}"><div><h3>${safe(child.name)}</h3><p>${c.qty} unidade(s) por kit · a partir de ${money(child.priceCents/100)}</p></div>${p.kitMode==='open'?`<label class="kit-check"><input type="checkbox" data-kit-include="${c.productId}" ${item.included?'checked':''}>Incluir</label>`:'<span class="required-item">Incluso</span>'}</div><div class="kit-item-options" ${item.included?'':'hidden'}>${attrs(child,item.attributes,c.productId)}${child.type==='simple'?'<p class="catalog-help">Produto simples · não requer escolhas.</p>':''}</div></article>`}).join('')}</div><p id="kit-count" class="stock-status"></p>`}
  function getShippingAmount(){const p=selectedProduct();try{return {subtotal:resolveSelection(products,p,selection,Number(document.querySelector('#product-quantity')?.value||1)).totalCents,incomplete:false}}catch{return {subtotal:0,incomplete:true}}}
  function selectedProduct(){return products[currentId]}
  function syncSummary(){const p=selectedProduct();if(!p)return;const qty=Number(document.querySelector('#product-quantity')?.value||1);const stock=document.querySelector('#stock-status');const price=document.querySelector('.detail-price');const button=document.querySelector('[data-discovery=buy]');button.disabled=false;
    if(p.type==='kit'){const n=Object.values(selection.items).filter(x=>x.included).length;document.querySelector('#kit-count').textContent=`${n} de ${p.components.length} produtos selecionados · mínimo 2.`;}
    try{const q=resolveSelection(products,p,selection,qty);price.textContent=money(q.unitCents/100);stock.textContent=p.type==='virtual'?'Arquivo digital · sem entrega física':p.type==='kit'?'Composição disponível. Valor por kit com os itens escolhidos.':'Disponível para a combinação selecionada.';if(p.type==='simple')stock.textContent='Disponível para compra.';stock.classList.remove('unavailable');}
    catch(error){stock.textContent=error.message;stock.classList.add('unavailable');if(error.message.includes('estoque insuficiente')||error.message.includes('combinação indisponível'))button.disabled=true;price.textContent=(p.type==='variable'||(p.type==='kit'&&p.kitMode==='open')?'A partir de ':'')+money(p.priceCents/100);}
    if(p.type!=='virtual')refreshProductShipping(p,getShippingAmount);
  }
  function mount(id){const p=products[id];if(!p)return;if(currentId!==id)selection=p.type==='kit'?{items:Object.fromEntries(p.components.map(c=>[c.productId,{included:p.kitMode==='closed',attributes:{}}]))}:{attributes:{}};currentId=id;
    const buy=document.querySelector('.product-buy');buy.querySelector('.variations')?.remove();const slot=document.createElement('div');slot.className='type-configuration';slot.innerHTML=p.type==='kit'?kitRows(p):p.type==='variable'?`<div class="type-label">Escolha as opções do produto</div>${attrs(p,selection.attributes)}`:'';buy.querySelector('#stock-status').before(slot);
    document.querySelectorAll('.product-information dl>div').forEach(row=>{if(row.querySelector('dt')?.textContent==='Variações')row.remove()});
    if(p.type==='variable')document.querySelector('.product-information dl').insertAdjacentHTML('beforeend',p.attributes.map(a=>`<div><dt>${safe(a.name)}</dt><dd>${a.values.map(safe).join(', ')}</dd></div>`).join(''));
    if(p.type==='kit')document.querySelector('.product-information>p').textContent=`Kit ${p.kitMode==='closed'?'fechado: todos os componentes são obrigatórios':'aberto: escolha no mínimo 2 produtos diferentes'}. Preço demonstrativo formado pela soma dos itens e variações selecionados. Estoque compartilhado com os produtos vendidos separadamente.`;
    if(p.type==='virtual'){buy.querySelector('.shipping-box')?.remove();buy.querySelector('.detail-price + p').textContent='Produto digital para download. Sem frete, despacho ou retirada.';buy.insertAdjacentHTML('beforeend',`<section class="digital-delivery"><span class="type-pill">Download digital</span><h2>Seu arquivo, na área de downloads.</h2><dl><dt>Formato</dt><dd>${safe(p.digital.format)}</dd><dt>Arquivo</dt><dd>${safe(p.digital.fileName)}</dd><dt>Licença demonstrativa</dt><dd>${safe(p.digital.license)}</dd></dl><p>Na operação real, o acesso será liberado após a confirmação do pagamento. Não inclui curso nem aulas em vídeo.</p><button class="btn secondary" data-type-action="downloads">Meus downloads (demonstração)</button></section>`);}
    mountProductShipping({product:p,getAmount:getShippingAmount,modal});syncSummary();
  }
  function syncCart(){state.cart.clear();lines.forEach(l=>state.cart.set(l.id,(state.cart.get(l.id)||0)+l.qty));document.querySelectorAll('.count').forEach(el=>el.textContent=[...state.cart.values()].reduce((a,b)=>a+b,0));}
  function showCart({addedKey=null,addedQty=0}={}){
    const previousScroll=document.querySelector('.drawer-content')?.scrollTop||0;let total=0,lastStore=null;const active=document.activeElement;const focusAction=active?.dataset.typeAction,focusLine=active?.dataset.line;
    const html=[...lines].sort((a,b)=>products[a[1].id].store-products[b[1].id].store).map(([key,l])=>{const p=products[l.id],q=resolveSelection(products,p,l.selection,l.qty);total+=q.totalCents;const heading=lastStore!==p.store?'<h3 class="cart-store-title">'+safe(readMarketplace().stores.find(store=>store.id===p.store)?.name||'Loja não disponível')+'</h3>':'';lastStore=p.store;
      return heading+'<article class="drawer-item '+(key===addedKey?'just-added':'')+'"><img class="drawer-item-image" src="'+safe(p.image)+'" alt="'+safe(p.name)+'"><div class="drawer-item-info"><b>'+safe(p.name)+'</b><small>'+TYPE_LABELS[p.type]+' · '+money(q.unitCents/100)+' por unidade</small>'+(q.parts.length?'<ul>'+q.parts.map(part=>'<li>'+part.componentQty*l.qty+'× '+safe(part.name)+(part.label?' — '+safe(part.label):'')+'</li>').join('')+'</ul>':q.label?'<p class="drawer-variation">'+safe(q.label)+'</p>':'')+(!productVisibleForPostal(p)?'<p class="delivery-unavailable">Este item não atende ao CEP atual. Altere a localização ou remova-o da sacola.</p>':'')+'<div class="drawer-item-bottom"><div class="drawer-quantity" aria-label="Quantidade de '+safe(p.name)+'"><button data-type-action="minus" data-line="'+key+'" aria-label="Diminuir quantidade de '+safe(p.name)+'">−</button><span>'+l.qty+'</span><button data-type-action="plus" data-line="'+key+'" aria-label="Aumentar quantidade de '+safe(p.name)+'">+</button></div><strong>'+money(q.totalCents/100)+'</strong></div><button class="text-link drawer-remove" data-type-action="remove" data-line="'+key+'">Remover item</button></div></article>';
    }).join('');
    const added=addedKey?lines.get(addedKey):null;
    modal('Sua sacola', '<div class="drawer-content">'+(added?'<div class="drawer-success" role="status">'+icon('check')+'<div><b>Produto adicionado à sacola</b><span>'+addedQty+' unidade(s) de '+safe(products[added.id].name)+'</span></div></div>':'')+(lines.size?html:'<div class="empty"><h3>Sua sacola está vazia</h3><p>Explore o catálogo e escolha seus produtos.</p></div>')+'</div><footer class="drawer-footer"><p id="cart-feedback" role="alert"></p>'+(lines.size?'<div class="drawer-total"><span>Subtotal dos produtos</span><strong>'+money(total/100)+'</strong></div><p>Frete calculado no checkout. Escolha entrega ou retirada para cada loja.</p><button class="btn" data-checkout>Continuar para o checkout →</button>':'')+'<button class="btn secondary" data-action="close">Continuar comprando</button></footer>','cart');
    if(addedKey)document.querySelector('.drawer-item.just-added')?.scrollIntoView({block:'nearest'});else document.querySelector('.drawer-content').scrollTop=previousScroll;
    if(focusLine&&!addedKey){const match=[...document.querySelectorAll('#modal [data-line]')].find(b=>b.dataset.line===focusLine&&b.dataset.typeAction===focusAction);(match||document.querySelector('#modal .close'))?.focus();}
  }
  document.addEventListener('change',e=>{if(e.target.id==='product-quantity')syncSummary();if(e.target.hasAttribute('data-attribute')){const comp=e.target.dataset.component;const target=comp!==undefined?selection.items[comp]:selection;target.attributes[e.target.dataset.attribute]=e.target.value;document.querySelector('#purchase-error').textContent='';syncSummary();}if(e.target.hasAttribute('data-kit-include')){selection.items[e.target.dataset.kitInclude].included=e.target.checked;const article=e.target.closest('.kit-item');article.classList.toggle('included',e.target.checked);article.querySelector('.kit-item-options').hidden=!e.target.checked;syncSummary();}});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-type-action],[data-discovery=buy],[data-discovery=open-cart],[data-action=cart]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const a=b.dataset.typeAction;
    if(b.dataset.action==='cart'||b.dataset.discovery==='open-cart'){showCart();return}
    if(b.dataset.discovery==='buy'){const p=selectedProduct(),qty=Number(document.querySelector('#product-quantity').value);try{if(!productVisibleForPostal(p))throw Error('Este produto não atende o CEP selecionado.');const quote=resolveSelection(products,p,selection,qty);const config=structuredClone(selection);const key=p.id+'-'+encodeURIComponent(JSON.stringify(config));const candidate={id:p.id,selection:config,qty:(lines.get(key)?.qty||0)+qty};validateCart(products,[...lines.entries()].filter(([k])=>k!==key).map(([,l])=>l).concat(candidate));lines.set(key,candidate);syncCart();document.querySelector('#purchase-error').textContent='';showCart({addedKey:key,addedQty:qty});}catch(error){document.querySelector('#purchase-error').textContent=error.message;}return}
    if(a==='cart'){showCart();return}if(a==='plus'||a==='minus'||a==='remove'){const l=lines.get(b.dataset.line);if(!l)return;const candidate={...l,qty:a==='remove'?0:l.qty+(a==='plus'?1:-1)};try{if(candidate.qty>0)validateCart(products,[...lines.entries()].filter(([k])=>k!==b.dataset.line).map(([,v])=>v).concat(candidate));if(candidate.qty<=0)lines.delete(b.dataset.line);else lines.set(b.dataset.line,candidate);syncCart();showCart();}catch(err){const feedback=document.querySelector('#cart-feedback');if(feedback)feedback.textContent=err.message;else toast(err.message)}return}
    if(a==='downloads'){journey.showOrders();return}
  },true);
  return {mount};
}

